<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>                    <a href="{pigcms{:U('infoList')}">信息已审核列表</a>|                    <a href="{pigcms{:U('Classify/replyList',array('vid'=>$vid))}" class="on">评论列表</a>                </ul>			</div>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<if condition="empty($_GET['cat_fid'])">								<col/>								<col/>								<col/>							</if>							<col/>						</colgroup>						<thead>							<tr>								<th>编号</th>								<th>评论内容</th>                                <th>评论者昵称</th>                                <th>被评论者昵称</th>                                <th>评论时间</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.reply_id}</td>                                        <td>{pigcms{$vo.content}</td>                                        <td>{pigcms{$vo.reply_nickname}</td>                                        <td>{pigcms{$vo.nickname}</td>                                        <td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>										<td class="textcenter">                                            <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Classify/reply_detail',array('reply_id'=>$vo['reply_id'],'frame_show'=>true))}','查看评论信息',480,260,true,false,false,false,'detail',true);">查看</a> |                                            <a href="javascript:void(0);" class="delete_row" parameter="reply_id={pigcms{$vo.reply_id}" url="{pigcms{:U('Classify/reply_del')}">删除</a></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="9">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="9">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>